const groupedData = {};

for (const item of $input.all()) {
  const data = item.json;

  // Dynamically extract values without relying on hardcoded fallbacks
  const ci = data.cmdb_ci;
  const category = data.category;

  // Create a dynamic group key based on the exact Category and CI combination
  const groupKey = `${category}_${ci}`;

  if (!groupedData[groupKey]) {
    groupedData[groupKey] = {
      category: category,
      affected_ci: ci,
      incidents: []
    };
  }

  // Add the incident to its matching dynamic group
  groupedData[groupKey].incidents.push(data);
}

const result = [];

// Output all groups without any hardcoded filtering
for (const key in groupedData) {
  result.push({ json: groupedData[key] });
}

return result;

