const problems = $input.item.json.data || [];

if (problems.length === 0) {
  return { 
    report_text: "✅ *Weekly Recurring Incident Report*\n_No recurring incident clusters met the threshold for escalation this week._" 
  };
}

let report = `🚨 *Weekly Recurring Incident Report*\n_Generated: ${new Date().toISOString().split('T')[0]}_\n\n*New Problem Records Created:*\n\n`;

problems.forEach((p, idx) => {
  const number = p.number || "Unknown PRB";
  const review = p.review_outcome || "";

  // Extract details from the AI's compiled text block
  const shortDescMatch = review.match(/Problem Short Description:\s*([^\n]*)/);
  const shortDesc = shortDescMatch ? shortDescMatch[1].trim() : "No description provided";

  const rootCauseMatch = review.match(/Root Cause:\s*([^\n]*)/);
  const rootCause = rootCauseMatch ? rootCauseMatch[1].trim() : "No root cause hypothesis";

  const recPriorityMatch = review.match(/recommended_priority:\s*([^\n]*)/);
  const recPriority = recPriorityMatch ? recPriorityMatch[1].trim() : p.priority;

  // Build the Slack markdown layout
  report += `*${idx + 1}. ${number}: ${shortDesc}*\n`;
  report += `> *Recommended Priority:* ${recPriority}\n`;
  report += `> *Root Cause Hypothesis:* ${rootCause}\n`;
  report += `> 🔗 <https://dev282039.service-now.com/problem.do?sys_id=${p.sys_id}|View Problem Record>\n\n`;
});

return { report_text: report.trim() };
